const $=s=>document.querySelector(s);let setup=false,currentView='dash';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(u,o={}){const r=await fetch(u,o);let j={};try{j=await r.json()}catch{}if(!r.ok){const d=j.detail;const msg=Array.isArray(d)?d.map(x=>x.msg||JSON.stringify(x)).join(', '):(typeof d==='object'&&d?JSON.stringify(d):d);throw Error(msg||'Požadavek selhal')}/* CARACAL_API_ERROR_FORMAT_V2 */;return j}function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2300)}async function boot(){setup=(await api('/api/setup-status')).needed;try{await api('/api/me');show()}catch{$('#mode').textContent=setup?'První spuštění: vytvoř účet správce':'Přihlášení správce'}}function show(){$('#login').hidden=true;$('#app').hidden=false;view('dash')}$('#loginForm').onsubmit=async e=>{e.preventDefault();try{await api(setup?'/api/setup':'/api/login',{method:'POST',body:new FormData(e.target)});show()}catch(x){$('#err').textContent=x.message}};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('#logoutBtn').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload()};$('#restartBtn').onclick=async()=>{await api('/api/player/restart',{method:'POST'});toast('Player se restartuje')};$('#refreshBtn').onclick=()=>view(currentView);$('#closeDlg').onclick=$('#cancelDlg').onclick=()=>dlg.close();async function view(v){currentView=v;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='dash')await dashboard();if(v==='assets')await assets();if(v==='profiles')await profiles()}async function dashboard(){const s=await api('/api/system'),a=await api('/api/assets');$('#title').textContent='Přehled';$('#subtitle').textContent='Stav zařízení a přehrávače';$('#content').innerHTML=`<div class=metrics><div class=metric><span>CPU</span><b>${s.cpu}%</b></div><div class=metric><span>RAM</span><b>${s.ram}%</b></div><div class=metric><span>Disk</span><b>${s.disk}%</b></div><div class=metric><span>Teplota</span><b>${s.temperature?.toFixed(1)??'N/A'} °C</b></div></div><div class=panel><div class=panel-head><h2>${esc(s.hostname)}</h2><span class=badge>${a.length} položek v playlistu</span></div><div class=row><div><div class=row-title>CARACAL běží</div><div class=muted>Uptime ${Math.floor(s.uptime/86400)} dní · správa na portu 8080</div></div><span class="badge auth">Online</span></div></div>`}function modal(t,h,fn){$('#dt').textContent=t;$('#db').innerHTML=h;dlg.showModal();$('#df').onsubmit=async e=>{e.preventDefault();const b=$('#saveDlg'),o=b.textContent;try{b.disabled=true;b.textContent='Ukládám…';await fn(new FormData(e.target));dlg.close();toast('Změny byly uloženy');await view(currentView)}catch(x){alert('Uložení selhalo: '+x.message)}finally{b.disabled=false;b.textContent=o}}}async function profilesOpts(selected=''){const p=await api('/api/profiles');return '<option value="">Bez přihlášení</option>'+p.map(x=>`<option value="${x.id}" ${Number(selected)===Number(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}async function assets(){const a=await api('/api/assets');$('#title').textContent='Playlist';$('#subtitle').textContent='Obsah, pořadí a délka zobrazení';$('#content').innerHTML=`<div class=panel><div class=panel-head><h2>Obsah playlistu</h2><div class=toolbar><button class=secondary onclick=upload()>Nahrát médium</button><button class=primary onclick=addUrl()>Přidat web</button></div></div>${a.map(x=>`<div class=row><div><div class=row-title>${esc(x.name)}</div><div class=muted>${esc(x.source)}</div><div class=meta><span class="badge ${x.kind==='web'?'web':''}">${x.kind}</span><span class=badge>${x.duration} s</span>${x.auth_profile_id?'<span class="badge auth">Automatické přihlášení</span>':''}${x.kind==='web'?`<span class=badge>${x.scale||1}×</span>`:''}</div></div><div class=actions>${x.kind==='web'?`<span class=scale-control><input id=sc${x.id} type=number min=.5 max=3 step=.1 value=${x.scale||1}><button class=secondary onclick=saveScale(${x.id})>Měřítko</button></span>`:''}<button class=secondary onclick=editAsset(${x.id})>Upravit</button><button class=danger onclick=delAsset(${x.id})>Smazat</button></div></div>`).join('')||'<div class=list-empty>Playlist je prázdný. Přidej první web nebo médium.</div>'}</div>`}async function saveScale(id){const e=$('#sc'+id);await api('/api/assets/'+id+'/scale',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scale:Number(e.value)})});toast('Měřítko uloženo')}async function delAsset(id){if(confirm('Opravdu smazat tuto položku?')){await api('/api/assets/'+id,{method:'DELETE'});toast('Položka odstraněna');assets()}}async function addUrl(){const o=await profilesOpts();modal('Přidat web',`<label>Název<input name=name required placeholder="Zabbix dashboard"></label><label>URL<input name=source required placeholder="https://..."></label><label>Doba zobrazení<input name=duration type=number min=5 value=30></label><label>Měřítko<input name=scale type=number min=.5 max=3 step=.1 value=1></label><label>Přihlašovací profil<select name=auth_profile_id>${o}</select></label>`,f=>api('/api/assets/url',{method:'POST',body:f}))}function upload(){modal('Nahrát médium','<label>Název<input name=name required></label><label>Doba zobrazení<input name=duration type=number min=5 value=15></label><label>Soubor<input name=file type=file accept="image/*,video/*" required></label>',f=>api('/api/assets/upload',{method:'POST',body:f}))}async function editAsset(id){const a=(await api('/api/assets')).find(x=>x.id===id),o=await profilesOpts(a.auth_profile_id);modal('Upravit položku',`<label>Název<input name=name value="${esc(a.name)}" required></label><label>Zdroj<input name=source value="${esc(a.source)}" ${a.kind==='web'?'required':'disabled'}></label><label>Doba zobrazení<input name=duration type=number min=5 value=${a.duration}></label>${a.kind==='web'?`<label>Měřítko<input name=scale type=number min=.5 max=3 step=.1 value=${a.scale||1}></label><label>Přihlašovací profil<select name=auth_profile_id>${o}</select></label>`:''}`,f=>api('/api/assets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(f.entries()))}))}async function profiles(){const p=await api('/api/profiles');$('#title').textContent='Přihlášení webů';$('#subtitle').textContent='Šifrované přihlašovací profily a CSS selektory';$('#content').innerHTML=`<div class=panel><div class=panel-head><h2>Přihlašovací profily</h2><button class=primary onclick=addProfile()>Nový profil</button></div>${p.map(x=>`<div class=row><div><div class=row-title>${esc(x.name)}</div><div class=muted>${esc(x.login_url)} → ${esc(x.target_url)}</div><div class=meta><span class="badge auth">Šifrováno</span><span class=badge>${esc(x.user_selector)}</span><span class=badge>${esc(x.pass_selector)}</span></div></div><div class=actions><button class=secondary onclick=editProfile(${x.id})>Upravit</button><button class=danger onclick=deleteProfile(${x.id})>Odebrat</button></div></div>`).join('')||'<div class=list-empty>Žádné profily. Vytvoř profil pro Zabbix nebo jiný web.</div>'}</div>`}function profileForm(p={}){return `<label>Název<input name=name value="${esc(p.name||'')}" required></label><label>Login URL<input name=login_url value="${esc(p.login_url||'')}" required></label><label>Cílová URL<input name=target_url value="${esc(p.target_url||'')}" required></label><label>Uživatel<input name=username placeholder="${p.id?'Prázdné = beze změny':'Uživatel'}" ${p.id?'':'required'}></label><label>Heslo<input name=password type=password placeholder="${p.id?'Prázdné = beze změny':'Heslo'}" ${p.id?'':'required'}></label><label>Selektor uživatele<input name=user_selector value="${esc(p.user_selector||'#name')}" required></label><label>Selektor hesla<input name=pass_selector value="${esc(p.pass_selector||'#password')}" required></label><label>Selektor tlačítka<input name=submit_selector value="${esc(p.submit_selector||'#enter')}" required></label>`}function addProfile(){modal('Nový přihlašovací profil',profileForm(),f=>api('/api/profiles',{method:'POST',body:f}))}async function editProfile(id){const p=(await api('/api/profiles')).find(x=>x.id===id);modal('Upravit profil',profileForm(p),f=>api('/api/profiles/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(f.entries()))}))}async function deleteProfile(id){if(confirm('Odebrat profil? Přiřazené weby zůstanou bez automatického přihlášení.')){await api('/api/profiles/'+id,{method:'DELETE'});toast('Profil odebrán');profiles()}}boot();

// CARACAL_THEME_UX_V2
(function(){
 const saved=localStorage.getItem('caracal-theme');
 const preferred=window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';
 const initial=saved||preferred;
 function applyTheme(theme){
  document.documentElement.dataset.theme=theme;
  localStorage.setItem('caracal-theme',theme);
  const icon=document.getElementById('themeIcon');
  const text=document.getElementById('themeText');
  if(icon)icon.textContent=theme==='dark'?'☀':'◐';
  if(text)text.textContent=theme==='dark'?'Světlý režim':'Tmavý režim';
 }
 applyTheme(initial);
 window.addEventListener('DOMContentLoaded',()=>{
  const btn=document.getElementById('themeBtn');
  if(btn)btn.addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
 });
})();


// CARACAL_UX_FIXED_V2
(function(){
 function byId(id){return document.getElementById(id)}
 window.openHelp=function(){byId('helpPanel')?.classList.add('open');byId('helpBackdrop')?.classList.add('open');byId('helpPanel')?.setAttribute('aria-hidden','false')};
 window.closeHelp=function(){byId('helpPanel')?.classList.remove('open');byId('helpBackdrop')?.classList.remove('open');byId('helpPanel')?.setAttribute('aria-hidden','true')};
 window.scalePreview=function(id,value){const v=byId('scaleValue'+id);if(v)v.textContent=value+' %'};
 window.setScalePreset=function(id,value){const r=byId('scaleRange'+id);if(r){r.value=value;window.scalePreview(id,value)}};
 window.saveScaleUX=async function(id){const r=byId('scaleRange'+id);if(!r)return;const pct=Number(r.value);try{await api('/api/assets/'+id+'/scale',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scale:pct/100})});toast('Měřítko '+pct+' % bylo uloženo')}catch(e){alert('Měřítko se nepodařilo uložit: '+e.message)}};
 window.rebootDevice=async function(){if(!confirm('Opravdu restartovat celé Raspberry Pi? Administrace bude přibližně minutu nedostupná.'))return;try{await api('/api/system/reboot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:'REBOOT'})});toast('Raspberry Pi se restartuje…');setTimeout(function(){location.reload()},65000)}catch(e){alert('Restart se nepodařilo spustit: '+e.message)}};
 window.caracalScaleControl=function(id,value){const pct=Math.round(Number(value||1)*100);return '<div class="scale-box"><div class="scale-label"><b>Velikost obsahu</b><span id="scaleValue'+id+'" class="scale-value">'+pct+' %</span></div><input id="scaleRange'+id+'" class="scale-range" type="range" min="50" max="300" step="5" value="'+pct+'" oninput="scalePreview('+id+',this.value)"><div class="scale-presets"><button type="button" onclick="setScalePreset('+id+',75)">75 %</button><button type="button" onclick="setScalePreset('+id+',100)">100 %</button><button type="button" onclick="setScalePreset('+id+',125)">125 %</button><button type="button" onclick="setScalePreset('+id+',150)">150 %</button><button type="button" class="primary" onclick="saveScaleUX('+id+')">Uložit</button></div><div class="scale-hint">100 % znamená původní velikost. Vyšší hodnota zvětší text i prvky webu.</div></div>'};
 const originalDashboard=window.dashboard;
 if(typeof originalDashboard==='function')window.dashboard=async function(){await originalDashboard();const content=byId('content');if(!content||content.querySelector('.quick-actions'))return;const box=document.createElement('div');box.className='quick-actions';box.innerHTML='<button class="quick-action" type="button" data-go="assets"><b>Přidat nebo upravit obsah</b><span>Weby, obrázky, videa a měřítko</span></button><button class="quick-action" type="button" data-go="profiles"><b>Spravovat přihlášení</b><span>Zabbix a další chráněné weby</span></button><button class="quick-action" type="button" data-help="1"><b>Otevřít nápovědu</b><span>Vysvětlení funkcí a doporučení</span></button>';box.querySelector('[data-go="assets"]').onclick=function(){view('assets')};box.querySelector('[data-go="profiles"]').onclick=function(){view('profiles')};box.querySelector('[data-help]').onclick=window.openHelp;content.insertBefore(box,content.children[1]||null)};
 const originalAssets=window.assets;
 if(typeof originalAssets==='function')window.assets=async function(){await originalAssets();const list=await api('/api/assets');for(const item of list){if(item.kind!=='web')continue;const old=byId('sc'+item.id);if(!old)continue;const holder=old.closest('.scale-control')||old.parentElement;holder.outerHTML=window.caracalScaleControl(item.id,item.scale||1)}};
 document.addEventListener('DOMContentLoaded',function(){byId('helpBtn')?.addEventListener('click',window.openHelp);byId('closeHelp')?.addEventListener('click',window.closeHelp);byId('helpBackdrop')?.addEventListener('click',window.closeHelp);byId('rebootBtn')?.addEventListener('click',window.rebootDevice);document.addEventListener('keydown',function(e){if(e.key==='Escape')window.closeHelp()})});
})();


// CARACAL_LIVE_CONTROL_UI_V1
window.caracalPlayerStatus=null;
window.liveCommand=async function(action){const sel=document.getElementById('liveAssetSelect');const body={action:action};if((action==='show'||action==='freeze')&&sel&&sel.value)body.asset_id=Number(sel.value);try{await api('/api/player/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast(action==='freeze'?'Položka byla zamražena':action==='unfreeze'?'Automatické přehrávání obnoveno':'Příkaz byl odeslán');setTimeout(refreshLiveControl,350)}catch(e){alert('Příkaz selhal: '+e.message)}};
window.refreshLiveControl=async function(){const root=document.getElementById('liveControl');if(!root)return;try{const s=await api('/api/player/status');window.caracalPlayerStatus=s;const name=document.getElementById('liveCurrentName'),state=document.getElementById('liveStateText'),dot=document.getElementById('liveDot'),count=document.getElementById('liveCountdown'),freeze=document.getElementById('liveFreezeBtn'),sel=document.getElementById('liveAssetSelect');if(name)name.textContent=s.current_name||'Žádná položka';if(dot)dot.classList.toggle('offline',!s.player_online);if(state)state.textContent=!s.player_online?'Player offline':s.frozen?'Zamraženo':'Přehrává se';if(count)count.textContent=s.frozen?'ZAMRAŽENO':s.remaining==null?'—':'Další za '+s.remaining+' s';if(freeze){freeze.textContent=s.frozen?'Odmrazit':'Zamrazit';freeze.classList.toggle('freeze-on',s.frozen);freeze.onclick=()=>liveCommand(s.frozen?'unfreeze':'freeze')}if(sel&&s.current_id&&!sel.matches(':focus'))sel.value=String(s.current_id)}catch(e){console.warn(e)}};
window.renderLiveControl=async function(){const assets=await api('/api/assets');return '<div id="liveControl" class="panel live-control"><div class="panel-head"><h2>Živé ovládání obrazovky</h2><span id="liveCountdown" class="countdown-chip">Načítám…</span></div><div class="live-now"><div class="live-state"><span id="liveDot" class="live-pulse offline"></span><div><div id="liveCurrentName" class="row-title">Načítám…</div><div id="liveStateText" class="muted">Čekám na player</div></div></div><button class="secondary" onclick="liveCommand(\'next\')">Další položka</button></div><div class="live-select"><select id="liveAssetSelect">'+assets.map(a=>'<option value="'+a.id+'">'+esc(a.name)+' · '+esc(a.kind)+'</option>').join('')+'</select><button class="primary" onclick="liveCommand(\'show\')">Zobrazit teď</button><button id="liveFreezeBtn" class="secondary">Zamrazit</button></div></div>'};
const caracalLiveDashboard=dashboard;dashboard=async function(){await caracalLiveDashboard();const content=document.getElementById('content');if(!content)return;const html=await renderLiveControl();content.insertAdjacentHTML('afterbegin',html);refreshLiveControl()};
setInterval(function(){if(document.getElementById('liveControl'))refreshLiveControl()},1000);


// CARACAL_LIVE_CONTROL_UI_V2
window.liveCommandV2=async function(action){const sel=document.getElementById('liveAssetSelect');const body={action:action};if((action==='show'||action==='freeze')&&sel&&sel.value)body.asset_id=Number(sel.value);try{await api('/api/v2/player/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast(action==='freeze'?'Položka zamražena':action==='unfreeze'?'Automatické přehrávání obnoveno':action==='next'?'Přepínám na další položku':'Přepínám obrazovku');setTimeout(refreshLiveV2,250)}catch(e){alert('Příkaz selhal: '+e.message)}};
window.refreshLiveV2=async function(){if(!document.getElementById('liveControlV2'))return;try{const s=await api('/api/v2/player/status');const q=id=>document.getElementById(id);q('liveNameV2').textContent=s.current_name||'Žádná položka';q('liveStateV2').textContent=!s.player_online?'Player offline':s.frozen?'Zamraženo':'Přehrává se';q('liveDotV2').classList.toggle('offline',!s.player_online);q('liveCountV2').textContent=s.frozen?'ZAMRAŽENO':s.remaining==null?'—':'Další za '+s.remaining+' s';const f=q('liveFreezeV2');f.textContent=s.frozen?'Odmrazit':'Zamrazit';f.classList.toggle('freeze-on',s.frozen);f.onclick=()=>liveCommandV2(s.frozen?'unfreeze':'freeze');const sel=q('liveAssetSelect');if(sel&&s.current_id&&!sel.matches(':focus'))sel.value=String(s.current_id)}catch(e){console.warn(e)}};
window.renderLiveV2=async function(){const a=await api('/api/assets');return '<div id="liveControlV2" class="panel live-control"><div class="panel-head"><h2>Živé ovládání obrazovky</h2><span id="liveCountV2" class="countdown-chip">Načítám…</span></div><div class="live-now"><div class="live-state"><span id="liveDotV2" class="live-pulse offline"></span><div><div id="liveNameV2" class="row-title">Načítám…</div><div id="liveStateV2" class="muted">Čekám na player</div></div></div><button class="secondary" onclick="liveCommandV2(\'next\')">Další položka</button></div><div class="live-select"><select id="liveAssetSelect">'+a.map(x=>'<option value="'+x.id+'">'+esc(x.name)+' · '+esc(x.kind)+'</option>').join('')+'</select><button class="primary" onclick="liveCommandV2(\'show\')">Zobrazit teď</button><button id="liveFreezeV2" class="secondary">Zamrazit</button></div></div>'};
const liveV2Dashboard=dashboard;dashboard=async function(){await liveV2Dashboard();document.getElementById('liveControl')?.remove();const content=document.getElementById('content');if(content&&!document.getElementById('liveControlV2')){content.insertAdjacentHTML('afterbegin',await renderLiveV2());refreshLiveV2()}};
setInterval(function(){if(document.getElementById('liveControlV2'))refreshLiveV2()},1000);


// CARACAL_KIOSK_FIX_UI_V3
window.setOverlayV3=async function(enabled){try{await api('/api/v3/player/overlay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:enabled})});toast(enabled?'Odpočet na TV zapnut':'Odpočet na TV vypnut');refreshOverlayV3()}catch(e){alert(e.message)}};
window.refreshOverlayV3=async function(){const b=document.getElementById('overlayToggleV3');if(!b)return;try{const s=await api('/api/v3/player/overlay-state');b.dataset.enabled=s.enabled?'1':'0';b.textContent=s.enabled?'Odpočet na TV: zapnutý':'Odpočet na TV: vypnutý';b.classList.toggle('freeze-on',s.enabled);b.onclick=()=>setOverlayV3(!s.enabled)}catch(e){console.warn(e)}};
window.restartPlayerV3=async function(){try{await api('/api/v3/player/restart',{method:'POST'});toast('Player se restartuje');setTimeout(refreshLiveV2,4000)}catch(e){alert('Restart selhal: '+e.message)}};
const kioskDashV3=dashboard;dashboard=async function(){await kioskDashV3();const panel=document.getElementById('liveControlV2');if(panel&&!document.getElementById('overlayToggleV3')){const row=panel.querySelector('.live-select');row.insertAdjacentHTML('beforeend','<button id="overlayToggleV3" class="secondary" type="button">Odpočet na TV</button><button class="secondary" type="button" onclick="restartPlayerV3()">Restart playeru</button>');refreshOverlayV3()}};
document.addEventListener('DOMContentLoaded',function(){const old=document.getElementById('restartBtn');if(old){const clone=old.cloneNode(true);old.replaceWith(clone);clone.onclick=restartPlayerV3}});


// CARACAL_PLAYLIST_REORDER_UI_V1
window.caracalDraggedRow=null;
window.caracalDragStart=function(event){const row=event.currentTarget;window.caracalDraggedRow=row;row.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',row.dataset.assetId)};
window.caracalDragOver=function(event){event.preventDefault();const row=event.currentTarget;if(row!==window.caracalDraggedRow){document.querySelectorAll('.playlist-sort-row').forEach(x=>x.classList.remove('drag-over'));row.classList.add('drag-over')}event.dataTransfer.dropEffect='move'};
window.caracalDrop=async function(event){event.preventDefault();const target=event.currentTarget;const dragged=window.caracalDraggedRow;if(!dragged||dragged===target)return;const list=document.getElementById('playlistSortable');const rect=target.getBoundingClientRect();const after=event.clientY>rect.top+rect.height/2;list.insertBefore(dragged,after?target.nextSibling:target);document.querySelectorAll('.playlist-sort-row').forEach(x=>x.classList.remove('drag-over','dragging'));window.caracalDraggedRow=null;await savePlaylistOrder()};
window.caracalDragEnd=function(){document.querySelectorAll('.playlist-sort-row').forEach(x=>x.classList.remove('drag-over','dragging'));window.caracalDraggedRow=null};
window.savePlaylistOrder=async function(){const list=document.getElementById('playlistSortable');if(!list)return;const ids=[...list.querySelectorAll('.playlist-sort-row')].map(x=>Number(x.dataset.assetId));list.classList.add('sort-saving');try{await api('/api/playlist/reorder',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:ids})});toast('Pořadí playlistu bylo uloženo');[...list.querySelectorAll('.playlist-sort-row')].forEach((row,i)=>{const badge=row.querySelector('.order-badge');if(badge)badge.textContent=i+1})}catch(e){alert('Pořadí nešlo uložit: '+e.message);await assets()}finally{list.classList.remove('sort-saving')}};
window.assets=async function(){const a=await api('/api/assets');document.getElementById('title').textContent='Playlist';document.getElementById('subtitle').textContent='Přetažením položek změníš pořadí přehrávání';const rows=a.map((x,index)=>'<div class="row playlist-sort-row" draggable="true" data-asset-id="'+x.id+'" ondragstart="caracalDragStart(event)" ondragover="caracalDragOver(event)" ondrop="caracalDrop(event)" ondragend="caracalDragEnd(event)"><div class="playlist-main"><div class="drag-handle" title="Přetáhni pro změnu pořadí">⋮⋮</div><div><div class="row-title"><span class="order-badge">'+(index+1)+'</span> '+esc(x.name)+'</div><div class="muted">'+esc(x.source)+'</div><div class="meta"><span class="badge '+(x.kind==='web'?'web':'')+'">'+esc(x.kind)+'</span><span class="badge">'+x.duration+' s</span>'+(x.auth_profile_id?'<span class="badge auth">Automatické přihlášení</span>':'')+(x.kind==='web'?'<span class="badge">'+(x.scale||1)+'×</span>':'')+'</div>'+(x.kind==='web'&&typeof caracalScaleControl==='function'?caracalScaleControl(x.id,x.scale||1):'')+'</div></div><div class="actions"><button class="secondary" onclick="editAsset('+x.id+')">Upravit</button><button class="danger" onclick="delAsset('+x.id+')">Smazat</button></div></div>').join('');document.getElementById('content').innerHTML='<div class="panel"><div class="panel-head"><div><h2>Obsah playlistu</h2><div class="sort-help"><b>⋮⋮</b><span>Uchop položku myší a přetáhni ji na nové místo</span></div></div><div class="toolbar"><button class="secondary" onclick="upload()">Nahrát médium</button><button class="primary" onclick="addUrl()">Přidat web</button></div></div><div id="playlistSortable">'+(rows||'<div class="list-empty">Playlist je prázdný. Přidej první web nebo médium.</div>')+'</div></div>'};
// Remove the redundant restart button added inside the live control panel. Header restart remains available.
window.removeExtraPlayerRestart=function(){document.querySelectorAll('#liveControlV2 .live-select button').forEach(button=>{if(button.textContent.trim()==='Restart playeru')button.remove()})};
const caracalReorderDashboard=dashboard;window.dashboard=async function(){await caracalReorderDashboard();setTimeout(removeExtraPlayerRestart,0)};
const caracalReorderRefresh=window.refreshLiveV2;if(typeof caracalReorderRefresh==='function')window.refreshLiveV2=async function(){await caracalReorderRefresh();removeExtraPlayerRestart()};


// CARACAL_DRAG_POLISH_V2
window.enablePolishedPlaylistDrag=function(){const list=document.getElementById('playlistSortable');if(!list||list.dataset.polished==='1')return;list.dataset.polished='1';let dragged=null;list.querySelectorAll('.playlist-sort-row').forEach(row=>{row.removeAttribute('draggable');row.removeAttribute('ondragstart');row.removeAttribute('ondragover');row.removeAttribute('ondrop');row.removeAttribute('ondragend');const handle=row.querySelector('.drag-handle');if(!handle)return;handle.setAttribute('draggable','true');handle.title='Uchop a přetáhni';handle.addEventListener('dragstart',event=>{dragged=row;row.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',row.dataset.assetId);requestAnimationFrame(()=>row.classList.add('dragging'))});handle.addEventListener('dragend',()=>{list.querySelectorAll('.playlist-sort-row').forEach(x=>x.classList.remove('dragging','drop-before','drop-after'));dragged=null})});list.addEventListener('dragover',event=>{event.preventDefault();if(!dragged)return;const target=event.target.closest('.playlist-sort-row');if(!target||target===dragged)return;list.querySelectorAll('.playlist-sort-row').forEach(x=>x.classList.remove('drop-before','drop-after'));const rect=target.getBoundingClientRect();target.classList.add(event.clientY<rect.top+rect.height/2?'drop-before':'drop-after');event.dataTransfer.dropEffect='move'});list.addEventListener('drop',async event=>{event.preventDefault();if(!dragged)return;const target=event.target.closest('.playlist-sort-row');if(!target||target===dragged)return;const before=target.classList.contains('drop-before');target.classList.remove('drop-before','drop-after');list.insertBefore(dragged,before?target:target.nextSibling);dragged.classList.remove('dragging');dragged=null;list.querySelectorAll('.playlist-sort-row').forEach(x=>x.classList.add('order-saving'));await savePlaylistOrder();list.querySelectorAll('.playlist-sort-row').forEach(x=>x.classList.remove('order-saving'))})};
const caracalPolishedAssets=window.assets;window.assets=async function(){await caracalPolishedAssets();enablePolishedPlaylistDrag()};


// CARACAL_REORDER_OVERLAY_SIZE_UI_V2
window.overlaySettingsV4=null;
window.loadOverlaySettingsV4=async function(){try{const s=await api('/api/v4/player/overlay-settings');window.overlaySettingsV4=s;const range=document.getElementById('overlaySizeV4'),value=document.getElementById('overlaySizeValueV4'),toggle=document.getElementById('overlayToggleV4');if(range){range.value=s.size;value.textContent=s.size+' px'}if(toggle){toggle.textContent=s.enabled?'Odpočet: zapnutý':'Odpočet: vypnutý';toggle.classList.toggle('freeze-on',s.enabled)}}catch(e){console.warn(e)}};
window.previewOverlaySizeV4=function(value){const x=document.getElementById('overlaySizeValueV4');if(x)x.textContent=value+' px'};
window.saveOverlaySizeV4=async function(){const range=document.getElementById('overlaySizeV4');if(!range)return;const enabled=window.overlaySettingsV4?window.overlaySettingsV4.enabled:true;try{await api('/api/v4/player/overlay-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:enabled,size:Number(range.value)})});toast('Velikost odpočtu byla uložena');await loadOverlaySettingsV4()}catch(e){alert('Velikost nešla uložit: '+e.message)}};
window.toggleOverlayV4=async function(){const size=Number(document.getElementById('overlaySizeV4')?.value||16);const enabled=!(window.overlaySettingsV4&&window.overlaySettingsV4.enabled);try{await api('/api/v4/player/overlay-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:enabled,size:size})});toast(enabled?'Odpočet na TV zapnut':'Odpočet na TV vypnut');await loadOverlaySettingsV4()}catch(e){alert(e.message)}};
window.injectOverlaySizeV4=function(){const panel=document.getElementById('liveControlV2');if(!panel||document.getElementById('overlaySizeV4'))return;const row=panel.querySelector('.live-select');if(!row)return;document.getElementById('overlayToggleV3')?.remove();row.insertAdjacentHTML('beforeend','<div class="overlay-size-control"><button id="overlayToggleV4" class="secondary" type="button" onclick="toggleOverlayV4()">Odpočet</button><label for="overlaySizeV4">Velikost</label><input id="overlaySizeV4" type="range" min="10" max="42" step="1" value="16" oninput="previewOverlaySizeV4(this.value)"><span id="overlaySizeValueV4" class="overlay-size-value">16 px</span><button class="secondary" type="button" onclick="saveOverlaySizeV4()">Uložit</button></div>');loadOverlaySettingsV4()};
const caracalOverlaySizeDashboard=window.dashboard;window.dashboard=async function(){await caracalOverlaySizeDashboard();setTimeout(injectOverlaySizeV4,0)};


// CARACAL_OVERLAY_DIRECT_INPUT_V1
window.syncOverlaySizeFromRangeV5=function(value){const number=document.getElementById('overlaySizeNumberV5');const legacy=document.getElementById('overlaySizeValueV4');if(number)number.value=value;if(legacy)legacy.textContent=value+' px'};
window.syncOverlaySizeFromNumberV5=function(value){let size=Math.max(10,Math.min(42,Number(value)||16));const range=document.getElementById('overlaySizeV4');const number=document.getElementById('overlaySizeNumberV5');if(range)range.value=size;if(number)number.value=size;const legacy=document.getElementById('overlaySizeValueV4');if(legacy)legacy.textContent=size+' px'};
const overlayPreviewOriginalV5=window.previewOverlaySizeV4;window.previewOverlaySizeV4=function(value){if(typeof overlayPreviewOriginalV5==='function')overlayPreviewOriginalV5(value);syncOverlaySizeFromRangeV5(value)};
window.injectOverlayDirectInputV5=function(){const range=document.getElementById('overlaySizeV4');if(!range||document.getElementById('overlaySizeNumberV5'))return;const legacy=document.getElementById('overlaySizeValueV4');if(legacy)legacy.style.display='none';range.insertAdjacentHTML('afterend','<input id="overlaySizeNumberV5" class="overlay-size-number" type="number" min="10" max="42" step="1" value="'+range.value+'" title="Klikni a napiš velikost v pixelech" oninput="syncOverlaySizeFromNumberV5(this.value)" onchange="syncOverlaySizeFromNumberV5(this.value)"><span class="overlay-size-unit">px</span>')};
const overlayLoadOriginalV5=window.loadOverlaySettingsV4;window.loadOverlaySettingsV4=async function(){if(typeof overlayLoadOriginalV5==='function')await overlayLoadOriginalV5();injectOverlayDirectInputV5();const size=window.overlaySettingsV4?window.overlaySettingsV4.size:16;syncOverlaySizeFromNumberV5(size)};
const overlayInjectOriginalV5=window.injectOverlaySizeV4;window.injectOverlaySizeV4=function(){if(typeof overlayInjectOriginalV5==='function')overlayInjectOriginalV5();setTimeout(injectOverlayDirectInputV5,0)};


// CARACAL_OVERLAY_ANY_SIZE_V1
window.syncOverlaySizeFromNumberAny=function(value){const raw=String(value).trim();if(raw==='')return;const size=Math.max(1,Math.round(Number(raw)||1));const range=document.getElementById('overlaySizeV4');const number=document.getElementById('overlaySizeNumberV5');if(range){range.max=Math.max(300,size);range.value=size}if(number)number.value=size;const legacy=document.getElementById('overlaySizeValueV4');if(legacy)legacy.textContent=size+' px'};
window.injectUnlimitedOverlaySize=function(){const number=document.getElementById('overlaySizeNumberV5');const range=document.getElementById('overlaySizeV4');if(number){number.min='1';number.removeAttribute('max');number.placeholder='px';number.title='Zadej libovolné kladné celé číslo';number.oninput=function(){syncOverlaySizeFromNumberAny(this.value)};number.onchange=function(){syncOverlaySizeFromNumberAny(this.value)}}if(range)range.max='300'};
const unlimitedInjectOriginal=window.injectOverlayDirectInputV5;window.injectOverlayDirectInputV5=function(){if(typeof unlimitedInjectOriginal==='function')unlimitedInjectOriginal();injectUnlimitedOverlaySize()};
const unlimitedSaveOriginal=window.saveOverlaySizeV4;window.saveOverlaySizeV4=async function(){const number=document.getElementById('overlaySizeNumberV5');const range=document.getElementById('overlaySizeV4');let size=Number(number&&number.value!==''?number.value:range?.value||16);size=Math.max(1,Math.round(size));const enabled=window.overlaySettingsV4?window.overlaySettingsV4.enabled:true;try{await api('/api/v4/player/overlay-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:enabled,size:size})});toast('Velikost odpočtu '+size+' px byla uložena');await loadOverlaySettingsV4()}catch(e){alert('Velikost nešla uložit: '+e.message)}};
setInterval(injectUnlimitedOverlaySize,1000);


// CARACAL_UNIFORM_SCALE_AND_INPUT_V2
window.caracalUnlimitedOverlayInput=function(){
 const number=document.getElementById('overlaySizeNumberV5');
 const range=document.getElementById('overlaySizeV4');
 const legacy=document.getElementById('overlaySizeValueV4');
 if(number){
  number.min='1';
  number.removeAttribute('max');
  number.step='1';
  number.title='Zadej libovolné kladné celé číslo v pixelech';
  number.oninput=function(){
   const raw=this.value.trim();
   if(raw==='')return;
   const size=Math.max(1,Math.round(Number(raw)||1));
   if(range){range.max=String(Math.max(300,size));range.value=String(size)}
   if(legacy)legacy.textContent=size+' px';
  };
 }
 if(range)range.max=String(Math.max(300,Number(number?.value||300)));
};
window.saveOverlaySizeV4=async function(){
 const number=document.getElementById('overlaySizeNumberV5');
 const range=document.getElementById('overlaySizeV4');
 let size=Math.round(Number(number&&number.value.trim()!==''?number.value:range?.value||16));
 if(!Number.isFinite(size)||size<1){alert('Zadej kladné celé číslo.');return}
 const enabled=window.overlaySettingsV4?Boolean(window.overlaySettingsV4.enabled):true;
 try{
  const saved=await api('/api/v4/player/overlay-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:enabled,size:size})});
  window.overlaySettingsV4=saved;
  if(number)number.value=String(saved.size);
  if(range){range.max=String(Math.max(300,saved.size));range.value=String(saved.size)}
  if(document.getElementById('overlaySizeValueV4'))document.getElementById('overlaySizeValueV4').textContent=saved.size+' px';
  toast('Velikost odpočtu '+saved.size+' px byla uložena');
 }catch(e){alert('Velikost nešla uložit: '+e.message)}
};
const caracalLoadOverlayUnlimitedV2=window.loadOverlaySettingsV4;
window.loadOverlaySettingsV4=async function(){
 let settings;
 try{settings=await api('/api/v4/player/overlay-settings');window.overlaySettingsV4=settings}catch(e){console.warn(e);return}
 const range=document.getElementById('overlaySizeV4');
 const number=document.getElementById('overlaySizeNumberV5');
 const legacy=document.getElementById('overlaySizeValueV4');
 const toggle=document.getElementById('overlayToggleV4');
 if(range){range.max=String(Math.max(300,settings.size));range.value=String(settings.size)}
 if(number){number.value=String(settings.size);number.min='1';number.removeAttribute('max')}
 if(legacy)legacy.textContent=settings.size+' px';
 if(toggle){toggle.textContent=settings.enabled?'Odpočet: zapnutý':'Odpočet: vypnutý';toggle.classList.toggle('freeze-on',settings.enabled)}
 caracalUnlimitedOverlayInput();
};
const caracalInjectUnlimitedV2=window.injectOverlayDirectInputV5;
window.injectOverlayDirectInputV5=function(){if(typeof caracalInjectUnlimitedV2==='function')caracalInjectUnlimitedV2();caracalUnlimitedOverlayInput()};
setInterval(caracalUnlimitedOverlayInput,750);


// CARACAL_GRAFANA_TAG_UI_V1
window.testGrafanaTag=async function(){const form=document.getElementById('df');const box=document.getElementById('grafanaDiscoverResult');if(!form||!box)return;const data=new FormData();data.set('grafana_url',form.elements.grafana_url.value);data.set('tag',form.elements.tag.value);box.className='grafana-summary';box.textContent='Hledám dashboardy…';try{const result=await api('/api/grafana/discover',{method:'POST',body:data});box.className='grafana-summary ok';box.innerHTML='<b>Nalezeno '+result.count+' dashboardů</b><br>'+result.dashboards.map(x=>esc(x.title)).join(' · ')}catch(e){box.className='grafana-summary error';box.textContent=e.message}};
window.addGrafanaTagCollection=function(){modal('Grafana dashboardy podle tagu','<div class="dialog-note">CARACAL použije Guest přístup k Grafana Search API a při každém cyklu automaticky načte všechny dashboardy s vybraným tagem.</div><label>Název kolekce<input name="name" required placeholder="Grafana NOC dashboardy"></label><label>URL Grafany<input name="grafana_url" required placeholder="https://grafana.example.cz"></label><label>Tag dashboardů<input name="tag" required placeholder="caracal-tv"></label><label>Doba jednoho dashboardu<input name="duration" type="number" min="5" value="60"></label><label>Měřítko<select name="scale"><option value="0.75">75 %</option><option value="1" selected>100 %</option><option value="1.25">125 %</option><option value="1.5">150 %</option></select></label><label><input name="kiosk" type="checkbox" checked style="width:auto;display:inline-block"> Přidat Grafana kiosk režim</label><div class="grafana-summary" id="grafanaDiscoverResult">Nejdřív můžeš ověřit, kolik dashboardů Guest účet vidí.</div><button type="button" class="secondary" onclick="testGrafanaTag()">Otestovat tag</button>',async formData=>{const result=await api('/api/assets/grafana-tag',{method:'POST',body:formData});toast('Kolekce přidána · '+result.dashboards+' dashboardů')})};
window.injectGrafanaTagButton=function(){const panel=document.querySelector('#content .panel');if(!panel)return;const toolbar=panel.querySelector('.panel-head .toolbar');if(toolbar&&!toolbar.querySelector('[data-grafana-tag]'))toolbar.insertAdjacentHTML('afterbegin','<button data-grafana-tag class="secondary" onclick="addGrafanaTagCollection()">Grafana podle tagu</button>');document.querySelectorAll('.playlist-sort-row').forEach(row=>{const kind=row.querySelector('.badge');if(kind&&kind.textContent.trim()==='grafana-tag'){kind.textContent='Grafana kolekce';kind.classList.add('grafana')}})};
const grafanaAssetsOriginal=window.assets;window.assets=async function(){await grafanaAssetsOriginal();injectGrafanaTagButton()};


// CARACAL_GRAFANA_COLLECTION_SCALE_UI_V1
window.grafanaScalePreview=function(id,value){const x=document.getElementById('grafanaScaleValue'+id);if(x)x.textContent=value+' %'};
window.setGrafanaScalePreset=function(id,value){const r=document.getElementById('grafanaScaleRange'+id);if(r){r.value=value;grafanaScalePreview(id,value)}};
window.saveGrafanaCollectionScale=async function(id){const r=document.getElementById('grafanaScaleRange'+id);if(!r)return;try{const result=await api('/api/grafana-collections/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scale:Number(r.value)/100})});toast('Měřítko kolekce '+Math.round(result.scale*100)+' % bylo uloženo')}catch(e){alert('Měřítko nešlo uložit: '+e.message)}};
window.grafanaCollectionScaleControl=function(id,scale){const pct=Math.round(Number(scale||1)*100);return '<div class="grafana-scale-box"><div class="grafana-scale-head"><b>Velikost všech dashboardů v kolekci</b><span id="grafanaScaleValue'+id+'" class="grafana-scale-value">'+pct+' %</span></div><input id="grafanaScaleRange'+id+'" type="range" min="50" max="300" step="5" value="'+pct+'" oninput="grafanaScalePreview('+id+',this.value)"><div class="grafana-scale-actions"><button class="secondary" onclick="setGrafanaScalePreset('+id+',75)">75 %</button><button class="secondary" onclick="setGrafanaScalePreset('+id+',100)">100 %</button><button class="secondary" onclick="setGrafanaScalePreset('+id+',125)">125 %</button><button class="secondary" onclick="setGrafanaScalePreset('+id+',150)">150 %</button><button class="primary" onclick="saveGrafanaCollectionScale('+id+')">Uložit měřítko</button></div></div>'};
window.editGrafanaCollection=async function(id){const item=(await api('/api/assets')).find(x=>Number(x.id)===Number(id));if(!item)return alert('Kolekce nebyla nalezena');let cfg={};try{cfg=JSON.parse(item.source||'{}')}catch{}modal('Upravit Grafana kolekci','<label>Název<input name="name" required value="'+esc(item.name)+'"></label><label>URL Grafany<input name="grafana_url" required value="'+esc(cfg.grafana_url||'')+'"></label><label>Tag<input name="tag" required value="'+esc(cfg.tag||'')+'"></label><label>Doba jednoho dashboardu<input name="duration" type="number" min="5" value="'+Number(item.duration||60)+'"></label><label>Měřítko<input name="scale" type="number" min="0.5" max="3" step="0.05" value="'+Number(item.scale||1)+'"></label><label><input name="kiosk" type="checkbox" '+(cfg.kiosk!==false?'checked':'')+' style="width:auto;display:inline-block"> Grafana kiosk režim</label>',async f=>{const payload=Object.fromEntries(f.entries());payload.kiosk=f.get('kiosk')==='on';payload.duration=Number(payload.duration);payload.scale=Number(payload.scale);const result=await api('/api/grafana-collections/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});toast('Kolekce upravena · '+result.dashboards+' dashboardů')})};
window.enhanceGrafanaCollectionRows=function(){document.querySelectorAll('.playlist-sort-row').forEach(row=>{const id=Number(row.dataset.assetId);const kind=row.querySelector('.badge');if(!kind||kind.textContent.trim()!=='Grafana kolekce')return;const source=row.querySelector('.muted')?.textContent||'';let scale=1;const scaleBadge=[...row.querySelectorAll('.badge')].find(x=>/^[0-9.]+×$/.test(x.textContent.trim()));if(scaleBadge)scale=parseFloat(scaleBadge.textContent)||1;const main=row.querySelector('.playlist-main>div:last-child');if(main&&!main.querySelector('.grafana-scale-box'))main.insertAdjacentHTML('beforeend',grafanaCollectionScaleControl(id,scale));const edit=[...row.querySelectorAll('.actions button')].find(x=>x.textContent.trim()==='Upravit');if(edit)edit.onclick=()=>editGrafanaCollection(id)})};
const grafanaScaleAssetsOriginal=window.assets;window.assets=async function(){await grafanaScaleAssetsOriginal();injectGrafanaTagButton();enhanceGrafanaCollectionRows()};


// CARACAL_UNIFORM_PLAYLIST_SCALE_V3
window.itemScalePreviewV3=function(id,value){const x=document.getElementById('itemScaleValueV3-'+id);if(x)x.textContent=value+' %'};
window.itemScalePresetV3=function(id,value){const r=document.getElementById('itemScaleRangeV3-'+id);if(r){r.value=value;itemScalePreviewV3(id,value)}};
window.itemScaleCardV3=function(item){const pct=Math.round(Number(item.scale||1)*100);return '<div class="item-scale-card"><div class="item-scale-head"><b>Velikost obsahu</b><span id="itemScaleValueV3-'+item.id+'" class="item-scale-value">'+pct+' %</span></div><input id="itemScaleRangeV3-'+item.id+'" class="item-scale-range" type="range" min="50" max="300" step="5" value="'+pct+'" oninput="itemScalePreviewV3('+item.id+',this.value)"><div class="item-scale-actions"><button class="secondary" type="button" onclick="itemScalePresetV3('+item.id+',75)">75 %</button><button class="secondary" type="button" onclick="itemScalePresetV3('+item.id+',100)">100 %</button><button class="secondary" type="button" onclick="itemScalePresetV3('+item.id+',125)">125 %</button><button class="secondary" type="button" onclick="itemScalePresetV3('+item.id+',150)">150 %</button><button class="item-scale-save" type="button" onclick="saveItemScaleV3('+item.id+',\''+item.kind+'\')">Uložit měřítko</button></div></div>'};
window.saveItemScaleV3=async function(id,kind){const r=document.getElementById('itemScaleRangeV3-'+id);if(!r)return;const scale=Number(r.value)/100;try{if(kind==='grafana-tag'){const item=(await api('/api/assets')).find(x=>Number(x.id)===Number(id));let cfg={};try{cfg=JSON.parse(item.source||'{}')}catch{};await api('/api/grafana-collections/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:item.name,grafana_url:cfg.grafana_url,tag:cfg.tag,duration:item.duration,scale:scale,kiosk:cfg.kiosk!==false})})}else{const item=(await api('/api/assets')).find(x=>Number(x.id)===Number(id));await api('/api/assets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:item.name,source:item.source,duration:item.duration,auth_profile_id:item.auth_profile_id,scale:scale})})}toast('Měřítko '+Math.round(scale*100)+' % bylo uloženo');await assets()}catch(e){alert('Měřítko nešlo uložit: '+e.message)}};
window.assets=async function(){const items=await api('/api/assets');document.getElementById('title').textContent='Playlist';document.getElementById('subtitle').textContent='Přetažením položek změníš pořadí přehrávání';const rows=items.map((item,index)=>{const scalable=item.kind==='web'||item.kind==='grafana-tag';const kindLabel=item.kind==='grafana-tag'?'Grafana kolekce':item.kind;const editAction=item.kind==='grafana-tag'?'editGrafanaCollection('+item.id+')':'editAsset('+item.id+')';return '<div class="row playlist-sort-row" data-asset-id="'+item.id+'"><div class="playlist-main"><div class="drag-handle" title="Uchop a přetáhni">⋮⋮</div><div><div class="row-title"><span class="order-badge">'+(index+1)+'</span> '+esc(item.name)+'</div><div class="muted">'+esc(item.source)+'</div><div class="meta"><span class="badge '+(item.kind==='grafana-tag'?'grafana':item.kind==='web'?'web':'')+'">'+esc(kindLabel)+'</span><span class="badge">'+Number(item.duration)+' s</span>'+(item.auth_profile_id?'<span class="badge auth">Automatické přihlášení</span>':'')+(scalable?'<span class="badge">'+Math.round(Number(item.scale||1)*100)+' %</span>':'')+'</div>'+(scalable?itemScaleCardV3(item):'')+'</div></div><div class="actions"><button class="secondary" onclick="'+editAction+'">Upravit</button><button class="danger" onclick="delAsset('+item.id+')">Smazat</button></div></div>'}).join('');document.getElementById('content').innerHTML='<div class="panel"><div class="panel-head"><div><h2>Obsah playlistu</h2><div class="sort-help"><b>⋮⋮</b><span>Uchop položku za úchyt a přetáhni ji na nové místo</span></div></div><div class="toolbar"><button data-grafana-tag class="secondary" onclick="addGrafanaTagCollection()">Grafana podle tagu</button><button class="secondary" onclick="upload()">Nahrát médium</button><button class="primary" onclick="addUrl()">Přidat web</button></div></div><div id="playlistSortable">'+(rows||'<div class="list-empty">Playlist je prázdný.</div>')+'</div></div>';if(typeof enablePolishedPlaylistDrag==='function')enablePolishedPlaylistDrag()};


