// CARACAL_SCALE_PERSIST_FIX_V7
window.saveItemScaleV3=async function(id,kind){
 const range=document.getElementById('itemScaleRangeV3-'+id);
 if(!range)return;
 const requested=Number(range.value)/100;
 try{
  const result=await api('/api/v7/assets/'+id+'/scale',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scale:requested})});
  const percent=Math.round(Number(result.scale)*100);
  range.value=String(percent);
  const value=document.getElementById('itemScaleValueV3-'+id);if(value)value.textContent=percent+' %';
  toast('Měřítko '+percent+' % bylo uloženo');
  setTimeout(function(){assets()},250);
 }catch(error){alert('Měřítko nešlo uložit: '+error.message)}
};
window.saveGrafanaCollectionScale=async function(id){
 const range=document.getElementById('grafanaScaleRange'+id)||document.getElementById('itemScaleRangeV3-'+id);
 if(!range)return;
 try{
  const result=await api('/api/v7/assets/'+id+'/scale',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scale:Number(range.value)/100})});
  const percent=Math.round(Number(result.scale)*100);toast('Měřítko kolekce '+percent+' % bylo uloženo');setTimeout(function(){assets()},250);
 }catch(error){alert('Měřítko nešlo uložit: '+error.message)}
};


// CARACAL_EDIT_SCALE_FIX_V8
window.parseCaracalScaleV8=function(value){
 const normalized=String(value??'').trim().replace(',','.');
 const scale=Number(normalized);
 if(!Number.isFinite(scale)||scale<0.5||scale>3)throw new Error('Měřítko musí být číslo od 0,5 do 3,0.');
 return scale;
};
window.editAsset=async function(id){
 const item=(await api('/api/assets')).find(x=>Number(x.id)===Number(id));
 if(!item){alert('Položka nebyla nalezena.');return}
 if(item.kind==='grafana-tag'){
  if(typeof editGrafanaCollection==='function'){editGrafanaCollection(id);return}
 }
 const options=typeof profilesOpts==='function'?await profilesOpts(item.auth_profile_id):'<option value="">Bez přihlášení</option>';
 const isWeb=item.kind==='web';
 const scaleText=Number(item.scale||1).toLocaleString('cs-CZ',{minimumFractionDigits:0,maximumFractionDigits:2});
 modal('Upravit položku',
  '<label>Název<input name="name" value="'+esc(item.name)+'" required></label>'+ 
  '<label>Zdroj<input name="source" value="'+esc(item.source)+'" '+(isWeb?'required':'disabled')+'></label>'+ 
  '<label>Doba zobrazení<input name="duration" type="number" value="'+Number(item.duration)+'" min="5" required></label>'+ 
  (isWeb?'<label>Měřítko obsahu<input name="scale" inputmode="decimal" value="'+scaleText+'" placeholder="např. 1,3"><span class="muted">0,5 = 50 %, 1 = 100 %, 1,3 = 130 %, 3 = 300 %</span></label><label>Přihlašovací profil<select name="auth_profile_id">'+options+'</select></label>':''),
  async formData=>{
   const payload={name:String(formData.get('name')||'').trim(),source:isWeb?String(formData.get('source')||'').trim():item.source,duration:Number(formData.get('duration')||item.duration),auth_profile_id:isWeb?(formData.get('auth_profile_id')||null):null};
   let scale=Number(item.scale||1);
   if(isWeb)scale=parseCaracalScaleV8(formData.get('scale'));
   await api('/api/assets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
   if(isWeb){
    const saved=await api('/api/v7/assets/'+id+'/scale',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scale:scale})});
    const pct=Math.round(Number(saved.scale)*100);
    toast('Položka uložena · měřítko '+pct+' %');
   }else toast('Položka byla uložena');
   setTimeout(()=>assets(),200);
  }
 );
};
// Replace Grafana collection editor so decimal comma is accepted and scale is verified through v7.
window.editGrafanaCollection=async function(id){
 const item=(await api('/api/assets')).find(x=>Number(x.id)===Number(id));
 if(!item){alert('Kolekce nebyla nalezena.');return}
 let cfg={};try{cfg=JSON.parse(item.source||'{}')}catch{}
 const scaleText=Number(item.scale||1).toLocaleString('cs-CZ',{minimumFractionDigits:0,maximumFractionDigits:2});
 modal('Upravit Grafana kolekci','<label>Název<input name="name" required value="'+esc(item.name)+'"></label><label>URL Grafany<input name="grafana_url" required value="'+esc(cfg.grafana_url||'')+'"></label><label>Tag<input name="tag" required value="'+esc(cfg.tag||'')+'"></label><label>Doba jednoho dashboardu<input name="duration" type="number" min="5" value="'+Number(item.duration||60)+'"></label><label>Měřítko obsahu<input name="scale" inputmode="decimal" value="'+scaleText+'" placeholder="např. 1,3"><span class="muted">Použít lze desetinnou čárku i tečku.</span></label><label><input name="kiosk" type="checkbox" '+(cfg.kiosk!==false?'checked':'')+' style="width:auto;display:inline-block"> Grafana kiosk režim</label>',async formData=>{
  const scale=parseCaracalScaleV8(formData.get('scale'));
  const payload={name:String(formData.get('name')||'').trim(),grafana_url:String(formData.get('grafana_url')||'').trim(),tag:String(formData.get('tag')||'').trim(),duration:Number(formData.get('duration')||60),scale:scale,kiosk:formData.get('kiosk')==='on'};
  const result=await api('/api/grafana-collections/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
  const saved=await api('/api/v7/assets/'+id+'/scale',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scale:scale})});
  toast('Kolekce uložena · '+result.dashboards+' dashboardů · '+Math.round(Number(saved.scale)*100)+' %');
  setTimeout(()=>assets(),200);
 });
};


// CARACAL_ADD_WEB_SCALE_FIX_V9
window.addUrl=async function(){
 const options=typeof profilesOpts==='function'?await profilesOpts():'<option value="">Bez přihlášení</option>';
 modal('Přidat web','<div class="dialog-note">Měřítko se uloží už při vytvoření. Lze použít desetinnou čárku i tečku.</div><label>Název<input name="name" required placeholder="Např. Zabbix dashboard"></label><label>URL<input name="source" required placeholder="https://..."></label><label>Doba zobrazení v sekundách<input name="duration" type="number" min="5" value="30" required></label><label>Měřítko obsahu<input name="scale" inputmode="decimal" value="1" placeholder="např. 1,3" required><span class="muted">0,5 = 50 %, 1 = 100 %, 1,3 = 130 %, 3 = 300 %</span></label><label>Přihlašovací profil<select name="auth_profile_id">'+options+'</select></label>',async formData=>{
  const rawScale=String(formData.get('scale')||'1').trim().replace(',','.');
  const scale=Number(rawScale);
  if(!Number.isFinite(scale)||scale<0.5||scale>3)throw new Error('Měřítko musí být číslo od 0,5 do 3,0.');
  const payload={name:String(formData.get('name')||'').trim(),source:String(formData.get('source')||'').trim(),duration:Number(formData.get('duration')||30),scale:scale,auth_profile_id:formData.get('auth_profile_id')||null};
  const result=await api('/api/v9/assets/web',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
  toast('Web přidán · měřítko '+Math.round(Number(result.scale)*100)+' %');
  setTimeout(()=>assets(),200);
 });
};


// CARACAL_NOTIFY_UI_V1
// "Oznámení" view: on-screen notification settings, the queue, and tokens for apps that send notifications.
(function(){
 const en=()=>localStorage.getItem('caracal-language')==='en',L=(cs,e)=>en()?e:cs;
 const LEVELS={info:['Info','Info','#3b82f6'],success:['OK','OK','#22c55e'],warning:['Varování','Warning','#f59e0b'],critical:['Kritické','Critical','#ef4444']};
 const POSITIONS=[['top-right','Vpravo nahoře','Top right'],['top','Nahoře uprostřed','Top centre'],['top-left','Vlevo nahoře','Top left'],['bottom-right','Vpravo dole','Bottom right'],['bottom','Dole uprostřed','Bottom centre'],['bottom-left','Vlevo dole','Bottom left'],['center','Uprostřed','Centre']];
 const SOUNDS=[['off','Jen na vyžádání oznámení','Only when a notification asks'],['critical','Jen kritická','Critical only'],['warning','Varování a kritická','Warning and critical'],['all','Všechna oznámení','All notifications']];
 const STATES={1:['Zobrazeno','Shown'],2:['Zahozeno / vypršelo','Dropped / expired'],3:['Odebráno','Removed']};
 const send=(method,body)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
 const when=t=>t?new Date(t*1000).toLocaleString(en()?'en-GB':'cs-CZ'):L('nikdy','never');
 const endpoint=()=>location.origin+'/api/notify/v1';
 let newToken=null;
 function level(l){const x=LEVELS[l]||LEVELS.info;return `<span class="badge ntf-level" style="--ntf:${x[2]}">${L(x[0],x[1])}</span>`}
 function note(n,extra,actions){return `<div class=row><div><div class=row-title>${esc(n.title||n.message)}</div>${n.title&&n.message?`<div class="muted ntf-message">${esc(n.message)}</div>`:''}<div class=meta>${level(n.level)}<span class=badge>${esc(n.source||'')}</span><span class=badge>${n.duration} s</span><span class=badge>${when(n.created)}</span>${extra||''}</div></div>${actions?`<div class=actions>${actions}</div>`:''}</div>`}
 function code(text){return `<div class=ntf-code><pre>${esc(text)}</pre><button class=secondary type=button onclick="ntfCopy(this)">${L('Kopírovat','Copy')}</button></div>`}
 function examples(token){
  const t=token||'<TOKEN>',u=endpoint();
  return code(`curl -X POST ${u} \\\n  -H "Authorization: Bearer ${t}" \\\n  -H "Content-Type: application/json" \\\n  -d '{"title":"Záloha dokončena","message":"Server DB01, 42 GB","level":"success"}'`)
   +code(`curl -H "Authorization: Bearer ${t}" -H "Title: Deploy" -H "X-Level: warning" \\\n  -d "Nasazení verze 2.4 začíná" ${u}`)
   +code(`Invoke-RestMethod -Method Post -Uri "${u}" -Headers @{Authorization="Bearer ${t}"} \`\n  -ContentType "application/json; charset=utf-8" \`\n  -Body (@{title="Tisk"; message="Došel toner"; level="warning"} | ConvertTo-Json)`);
 }
 async function queuePanel(){
  const q=await api('/api/notify/queue');
  const current=q.current?note(q.current,`<span class="badge auth">${L('Na obrazovce','On screen')} · ${Math.max(0,Math.ceil(q.current.shown_at+q.current.duration-q.now))} s</span>`,`<button class=secondary onclick=ntfSkip()>${L('Přeskočit','Skip')}</button>`):'';
  const waiting=q.waiting.map(n=>note(n,'',`<button class=danger onclick=ntfRemove(${n.id})>${L('Odebrat','Remove')}</button>`)).join('');
  return `<div class=panel-head><h2>${L('Fronta na obrazovce','Screen queue')}</h2><div class=toolbar><span class=badge>${q.waiting.length} ${L('čeká','waiting')}</span><button class=secondary onclick=ntfTest()>${L('Poslat test','Send test')}</button><button class=danger-outline onclick=ntfClear()>${L('Vyprázdnit','Clear')}</button></div></div>${current+waiting||`<div class=list-empty>${L('Nic nečeká. Oznámení se zobrazují po jednom, důležitější mají přednost.','Nothing is waiting. Notifications are shown one at a time, more important ones first.')}</div>`}`
   +`<div class=panel-head><h2>${L('Poslední oznámení','Recent notifications')}</h2><div class=toolbar><span class=badge>${q.history_count} ${L('záznamů v historii','entries in history')}</span><button class=danger-outline onclick=ntfClearHistory()>${L('Smazat historii','Clear history')}</button></div></div>${q.history.map(n=>note(n,`<span class=badge>${L(...(STATES[n.done]||STATES[1]))}</span>`)).join('')||`<div class=list-empty>${L('Zatím žádná.','None yet.')}</div>`}`;
 }
 window.ntfRefreshQueue=async function(){const box=document.getElementById('ntfQueue');if(!box||document.hidden)return;try{box.innerHTML=await queuePanel()}catch(e){console.warn(e)}};
 window.notifications=async function(){
  const [s,tokens]=await Promise.all([api('/api/notify/settings'),api('/api/notify/tokens')]);
  $('#title').textContent=L('Oznámení','Notifications');$('#subtitle').textContent=L('Vyskakovací oznámení na obrazovce z jiných aplikací','On-screen pop-up notifications from other apps');
  const fresh=newToken?`<div class="panel ntf-new"><div class=panel-head><h2>${L('Token pro','Token for')} ${esc(newToken.name)}</h2><button class=secondary onclick=ntfHideToken()>${L('Hotovo','Done')}</button></div><div class=ntf-body><p class=muted>${L('Token se zobrazí jen teď. Ulož ho do aplikace, která bude oznámení posílat. Zařízení si pamatuje jen jeho otisk.','The token is shown only now. Store it in the app that will send notifications. The device keeps only its hash.')}</p>${code(newToken.token)}${examples(newToken.token)}</div></div>`:'';
  const tokenRows=tokens.map(t=>`<div class=row><div><div class=row-title>${esc(t.name)}</div><div class=meta><span class=badge>${esc(t.prefix)}…</span><span class=badge>${t.rate_per_min} / min</span><span class="badge ${t.enabled?'auth':''}">${t.enabled?L('Povoleno','Enabled'):L('Zakázáno','Disabled')}</span><span class=badge>${L('Naposledy','Last used')}: ${when(t.last_used)}</span></div></div><div class=actions><button class=secondary onclick="ntfTokenEdit(${t.id})">${L('Upravit','Edit')}</button><button class=secondary onclick="ntfTokenToggle(${t.id},${t.enabled?0:1})">${t.enabled?L('Zakázat','Disable'):L('Povolit','Enable')}</button><button class=danger onclick="ntfTokenDelete(${t.id})">${L('Smazat','Delete')}</button></div></div>`).join('');
  $('#content').innerHTML=fresh
   +`<div class=panel id=ntfQueue>${await queuePanel()}</div>`
   +`<div class=panel><div class=panel-head><h2>${L('Nastavení','Settings')}</h2><button class=primary onclick=ntfSaveSettings()>${L('Uložit','Save')}</button></div><div class=ntf-settings>`
   +`<label class=ntf-check><input id=ntfEnabled type=checkbox ${s.enabled?'checked':''}> ${L('Zobrazovat oznámení','Show notifications')}</label>`
   +`<label>${L('Pozice','Position')}<select id=ntfPosition>${POSITIONS.map(p=>`<option value=${p[0]} ${s.position===p[0]?'selected':''}>${L(p[1],p[2])}</option>`).join('')}</select></label>`
   +`<label>${L('Doba zobrazení (s)','Display time (s)')}<input id=ntfDuration type=number min=3 max=120 value=${s.duration}></label>`
   +`<label>${L('Velikost (%)','Size (%)')}<input id=ntfScale type=number min=50 max=300 step=10 value=${s.scale}></label>`
   +`<label>${L('Max. ve frontě','Max. in queue')}<input id=ntfMaxQueue type=number min=1 max=200 value=${s.max_queue}></label>`
   +`<label>${L('Zvuk','Sound')}<select id=ntfSound>${SOUNDS.map(x=>`<option value=${x[0]} ${s.sound===x[0]?'selected':''}>${L(x[1],x[2])}</option>`).join('')}</select></label>`
   +`<label>${L('Hlasitost (%)','Volume (%)')}<input id=ntfVolume type=number min=0 max=100 step=10 value=${s.volume}></label>`
   +`<label>${L('Historie: max. záznamů','History: max. entries')}<input id=ntfHistoryMax type=number min=50 max=5000 step=50 value=${s.history_max}></label>`
   +`<label>${L('Historie: max. dní','History: max. days')}<input id=ntfHistoryDays type=number min=1 max=90 value=${s.history_days}></label>`
   +`<label>${L('Zvukový výstup (ALSA)','Sound output (ALSA)')}<input id=ntfSoundDevice value="${esc(s.sound_device||'')}" placeholder="${L('prázdné = výchozí, např. hdmi:CARD=vc4hdmi0,DEV=0','empty = default, e.g. hdmi:CARD=vc4hdmi0,DEV=0')}"></label>`
   +`<p class=muted>${L('Kritická oznámení zůstávají nejméně 15 s. Zvuk hraje zařízení přes HDMI nebo zvukový výstup, jinou znělkou pro každou úroveň; hlasitost 0 % obrazovku úplně ztlumí. Plná fronta zahodí nejstarší méně důležité oznámení, oznámení se stejným klíčem (key) se nahrazují místo hromadění.','Critical notifications stay at least 15 s. The device plays the sound through HDMI or its audio output, with a different chime per level; volume 0 % mutes the screen completely. A full queue drops the oldest less important notification; notifications with the same key replace each other instead of piling up.')}</p></div></div>`
   +`<div class=panel><div class=panel-head><h2>${L('Aplikace a tokeny','Apps and tokens')}</h2><button class=primary onclick=ntfTokenAdd()>${L('Nový token','New token')}</button></div>${tokenRows||`<div class=list-empty>${L('Zatím žádná aplikace. Každá aplikace dostane vlastní token, který jde kdykoli zakázat nebo smazat.','No apps yet. Every app gets its own token that can be disabled or deleted at any time.')}</div>`}</div>`
   +`<div class=panel><div class=panel-head><h2>${L('Jak posílat oznámení','How to send notifications')}</h2></div><div class=ntf-body><p class=muted>${L('POST na adresu níže s tokenem v hlavičce Authorization: Bearer (nebo X-Caracal-Token, nebo jako heslo v Basic auth). Pole: title, message, level (info, success, warning, critical), duration, key. Přímo rozumí webhookům z Grafany, Alertmanageru a Uptime Kuma – stačí jim zadat tuto URL a token.','POST to the address below with the token in the Authorization: Bearer header (or X-Caracal-Token, or as the Basic auth password). Fields: title, message, level (info, success, warning, critical), duration, key. Webhooks from Grafana, Alertmanager and Uptime Kuma work as they are: give them this URL and the token.')}</p>${code(endpoint())}${examples()}</div></div>`;
 };
 window.ntfCopy=async function(button){const text=button.previousElementSibling.textContent;try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();document.execCommand('copy');area.remove()}toast(L('Zkopírováno','Copied'))};
 window.ntfHideToken=function(){newToken=null;notifications()};
 window.ntfSaveSettings=async function(){try{await api('/api/notify/settings',send('PUT',{enabled:$('#ntfEnabled').checked,position:$('#ntfPosition').value,duration:Number($('#ntfDuration').value),scale:Number($('#ntfScale').value),max_queue:Number($('#ntfMaxQueue').value),sound:$('#ntfSound').value,volume:Number($('#ntfVolume').value),sound_device:$('#ntfSoundDevice').value.trim(),history_max:Number($('#ntfHistoryMax').value),history_days:Number($('#ntfHistoryDays').value)}));toast(L('Nastavení oznámení uloženo','Notification settings saved'))}catch(e){alert(e.message)}};
 window.ntfTest=function(){modal(L('Testovací oznámení','Test notification'),`<label>${L('Nadpis','Title')}<input name=title value="${esc(L('Test oznámení','Test notification'))}"></label><label>${L('Text','Message')}<input name=message value="${esc(L('Takhle vypadá oznámení na obrazovce.','This is how a notification looks on screen.'))}"></label><label>${L('Úroveň','Level')}<select name=level>${Object.entries(LEVELS).map(([k,v])=>`<option value=${k}>${L(v[0],v[1])}</option>`).join('')}</select></label><label>${L('Doba zobrazení (s, prázdné = výchozí)','Display time (s, empty = default)')}<input name=duration type=number min=3 max=120></label><label>${L('Zvuk','Sound')}<select name=sound><option value=''>${L('Podle nastavení','By the settings')}</option><option value=1>${L('Zahrát','Play')}</option><option value=0>${L('Bez zvuku','Silent')}</option></select></label>`,f=>api('/api/notify/test',send('POST',Object.fromEntries(f.entries()))))};
 window.ntfClearHistory=async function(){if(!confirm(L('Smazat celou historii oznámení? Čekající oznámení zůstanou.','Delete the whole notification history? Waiting notifications stay.')))return;const r=await api('/api/notify/history/clear',{method:'POST'});toast(L('Smazáno záznamů: ','Entries deleted: ')+r.deleted);ntfRefreshQueue()};
 window.ntfSkip=async function(){await api('/api/notify/skip',{method:'POST'});ntfRefreshQueue()};
 window.ntfRemove=async function(id){await api('/api/notify/queue/'+id,{method:'DELETE'});ntfRefreshQueue()};
 window.ntfClear=async function(){if(!confirm(L('Odebrat všechna čekající oznámení i to, které je právě na obrazovce?','Remove all waiting notifications and the one on screen?')))return;const r=await api('/api/notify/clear',{method:'POST'});toast(L('Odebráno: ','Removed: ')+r.cleared);ntfRefreshQueue()};
 window.ntfTokenAdd=function(){modal(L('Nový token','New token'),`<div class=dialog-note>${L('Jeden token pro jednu aplikaci (Grafana, zálohy, Home Assistant…). Název se zobrazí u oznámení.','One token per app (Grafana, backups, Home Assistant…). The name is shown on its notifications.')}</div><label>${L('Název aplikace','App name')}<input name=name required placeholder="Grafana"></label><label>${L('Limit oznámení za minutu','Notifications per minute')}<input name=rate_per_min type=number min=1 max=600 value=30></label>`,async f=>{const r=await api('/api/notify/tokens',send('POST',{name:f.get('name'),rate_per_min:Number(f.get('rate_per_min'))}));newToken={name:String(f.get('name')),token:r.token}})};
 window.ntfTokenEdit=async function(id){const t=(await api('/api/notify/tokens')).find(x=>x.id===id);if(!t)return;modal(L('Upravit token','Edit token'),`<label>${L('Název aplikace','App name')}<input name=name required value="${esc(t.name)}"></label><label>${L('Limit oznámení za minutu','Notifications per minute')}<input name=rate_per_min type=number min=1 max=600 value=${t.rate_per_min}></label>`,f=>api('/api/notify/tokens/'+id,send('PUT',{name:f.get('name'),rate_per_min:Number(f.get('rate_per_min'))})))};
 window.ntfTokenToggle=async function(id,enabled){await api('/api/notify/tokens/'+id,send('PUT',{enabled:!!enabled}));notifications()};
 window.ntfTokenDelete=async function(id){if(!confirm(L('Smazat token? Aplikace, která ho používá, už nebude moct posílat oznámení.','Delete the token? The app using it will no longer be able to send notifications.')))return;await api('/api/notify/tokens/'+id,{method:'DELETE'});notifications()};
 const viewBeforeNotify=window.view;
 window.view=async function(v){if(v!=='notify')return viewBeforeNotify(v);currentView=v;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));await notifications()};
 setInterval(function(){if(currentView==='notify')ntfRefreshQueue()},2000);
})();


// CARACAL_NOTIFY_WATCHERS_UI_V1
// Watchers: CARACAL asks another app's API for new items (tickets, issues, ...) and shows them as notifications.
(function(){
 const en=()=>localStorage.getItem('caracal-language')==='en',L=(cs,e)=>en()?e:cs;
 const send=(method,body)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
 const when=t=>t?new Date(t*1000).toLocaleString(en()?'en-GB':'cs-CZ'):L('zatím ne','not yet');
 const AUTH=[['none','Bez přihlášení','None'],['bearer','Bearer token','Bearer token'],['basic','Jméno a heslo / API klíč (Basic)','User and password / API key (Basic)'],['header','Vlastní hlavička','Custom header'],['oauth2','OAuth2','OAuth2']];
 const GRANTS=[['client_credentials','Client credentials (server–server)','Client credentials (server to server)'],['password','Password (technický uživatel)','Password (service user)'],['refresh_token','Refresh token','Refresh token']];
 const CLIENT_AUTH=[['body','V těle požadavku (client_secret_post)','In the request body (client_secret_post)'],['basic','Basic hlavička (client_secret_basic)','Basic header (client_secret_basic)']];
 const LEVELS=[['info','Info','Info'],['success','OK','OK'],['warning','Varování','Warning'],['critical','Kritické','Critical']];
 // the URLs are examples: replace the server, project and filter
 const PRESETS={
  custom:{label:['Vlastní API (JSON)','Custom API (JSON)']},
  zammad:{label:['Zammad – nové tickety','Zammad – new tickets'],url:'https://zammad.firma.cz/api/v1/tickets/search?query=state.name:new&sort_by=created_at&order_by=desc&limit=50&expand=true',auth_type:'header',auth_header:'Authorization',secret_hint:'Token token=…',list_path:'',id_field:'id',title_template:'Nový ticket #{number}: {title}',message_template:'{customer} · {group}',level_field:''},
  jira:{label:['Jira – nové issues','Jira – new issues'],url:'https://firma.atlassian.net/rest/api/3/search/jql?jql=project%3DSD%20AND%20statusCategory%3D%22To%20Do%22%20ORDER%20BY%20created%20DESC&fields=summary,priority,reporter&maxResults=50',auth_type:'basic',username_hint:'e-mail',secret_hint:'API token',list_path:'issues',id_field:'key',title_template:'{key}: {fields.summary}',message_template:'{fields.reporter.displayName}',level_field:'fields.priority.name'},
  redmine:{label:['Redmine – nové úkoly','Redmine – new issues'],url:'https://redmine.firma.cz/issues.json?status_id=open&sort=created_on:desc&limit=50',auth_type:'header',auth_header:'X-Redmine-API-Key',secret_hint:'API klíč',list_path:'issues',id_field:'id',title_template:'#{id}: {subject}',message_template:'{project.name} · {author.name}',level_field:'priority.name'},
  freshdesk:{label:['Freshdesk – nové tickety','Freshdesk – new tickets'],url:'https://firma.freshdesk.com/api/v2/tickets?order_by=created_at&order_type=desc&per_page=50',auth_type:'basic',username_hint:'API klíč',secret_hint:'X',list_path:'',id_field:'id',title_template:'Nový ticket #{id}: {subject}',message_template:'',level_field:''},
  gitlab:{label:['GitLab – nové issues','GitLab – new issues'],url:'https://gitlab.firma.cz/api/v4/projects/123/issues?state=opened&order_by=created_at&per_page=50',auth_type:'header',auth_header:'PRIVATE-TOKEN',secret_hint:'Personal access token',list_path:'',id_field:'id',title_template:'#{iid}: {title}',message_template:'{author.name}',level_field:''},
  graph:{label:['Microsoft 365 – nové e-maily ve schránce (OAuth2)','Microsoft 365 – new e-mails in a mailbox (OAuth2)'],url:'https://graph.microsoft.com/v1.0/users/helpdesk@firma.cz/mailFolders/inbox/messages?$top=25&$orderby=receivedDateTime%20desc&$select=subject,from,receivedDateTime,importance',auth_type:'oauth2',oauth_token_url:'https://login.microsoftonline.com/<TENANT-ID>/oauth2/v2.0/token',oauth_grant:'client_credentials',oauth_scope:'https://graph.microsoft.com/.default',oauth_client_auth:'body',oauth_extra:'',list_path:'value',id_field:'id',title_template:'{subject}',message_template:'{from.emailAddress.name}',level_field:''},
  servicenow:{label:['ServiceNow – nové incidenty (OAuth2)','ServiceNow – new incidents (OAuth2)'],url:'https://firma.service-now.com/api/now/table/incident?sysparm_query=active%3Dtrue%5EORDERBYDESCsys_created_on&sysparm_limit=50&sysparm_fields=sys_id,number,short_description,priority,category',auth_type:'oauth2',oauth_token_url:'https://firma.service-now.com/oauth_token.do',oauth_grant:'password',oauth_scope:'',oauth_client_auth:'body',oauth_extra:'',username_hint:'technický uživatel',list_path:'result',id_field:'sys_id',title_template:'{number}: {short_description}',message_template:'{category}',level_field:''},
  oauth:{label:['Vlastní API s OAuth2','Custom API with OAuth2'],url:'',auth_type:'oauth2',oauth_token_url:'https://login.firma.cz/realms/firma/protocol/openid-connect/token',oauth_grant:'client_credentials',oauth_scope:'',oauth_client_auth:'body',oauth_extra:'',list_path:'',id_field:'id',title_template:'',message_template:'',level_field:''},
  github:{label:['GitHub – nové issues','GitHub – new issues'],url:'https://api.github.com/repos/OWNER/REPO/issues?state=open&sort=created&per_page=50',auth_type:'bearer',secret_hint:'Personal access token',list_path:'',id_field:'id',title_template:'#{number}: {title}',message_template:'{user.login}',level_field:''}
 };
 function field(form,name){return form.querySelector(`[name="${name}"]`)}
 function payload(form,id){const f=new FormData(form),out=Object.fromEntries(f.entries());delete out.preset;out.interval=Number(out.interval||60);out.verify_tls=field(form,'verify_tls').checked;if(id)out.id=id;return out}
 window.wchAuthFields=function(){const form=document.getElementById('df');if(!form)return;const type=field(form,'auth_type').value,grant=field(form,'oauth_grant').value;form.querySelectorAll('[data-auth]').forEach(x=>{x.hidden=!x.dataset.auth.split(' ').includes(type)||(type==='oauth2'&&x.dataset.grant!==undefined&&!x.dataset.grant.split(' ').includes(grant))})};
 window.wchPreset=function(key){const form=document.getElementById('df'),p=PRESETS[key];if(!form||!p||key==='custom')return;for(const name of ['url','auth_type','auth_header','list_path','id_field','title_template','message_template','level_field','oauth_token_url','oauth_grant','oauth_scope','oauth_client_auth','oauth_extra'])if(p[name]!==undefined)field(form,name).value=p[name];if(!field(form,'name').value)field(form,'name').value=L(p.label[0],p.label[1]).split(' – ')[0];field(form,'username').placeholder=p.username_hint||'';field(form,'secret').placeholder=p.secret_hint||'';wchAuthFields()};
 window.wchPreview=async function(id){const form=document.getElementById('df'),box=document.getElementById('wchPreviewBox');if(!form||!box)return;box.innerHTML=`<div class=dialog-note>${L('Zkouším…','Trying…')}</div>`;try{const r=await api('/api/notify/watchers/preview',send('POST',payload(form,id)));box.innerHTML=`<div class=dialog-note><b>${L('Nalezeno položek','Items found')}: ${r.count}</b>${r.samples.map(x=>`<div class=wch-sample><b>${esc(x.title)}</b>${x.message?`<br>${esc(x.message)}`:''} <span class=muted>(${esc(x.level)})</span></div>`).join('')||`<br>${L('Seznam je teď prázdný – to je v pořádku, nové položky se ukážou, až přibudou.','The list is empty right now – that is fine, new items show up when they appear.')}`}</div>`}catch(e){box.innerHTML=`<div class="dialog-note wch-error">${esc(e.message)}</div>`}};
 function form(w,isNew){
  const keep=L('Prázdné = beze změny','Empty = unchanged');
  const opt=(list,value)=>list.map(x=>`<option value=${x[0]} ${value===x[0]?'selected':''}>${L(x[1],x[2])}</option>`).join('');
  return (isNew?`<label>${L('Předvolba','Preset')}<select name=preset onchange="wchPreset(this.value)">${Object.entries(PRESETS).map(([k,p])=>`<option value=${k}>${L(p.label[0],p.label[1])}</option>`).join('')}</select></label>`:'')
   +`<label>${L('Název (zobrazí se u oznámení)','Name (shown on notifications)')}<input name=name required value="${esc(w.name||'')}" placeholder="Helpdesk"></label>`
   +`<label class=wch-wide>${L('URL API (vrací JSON)','API URL (returns JSON)')}<input name=url required value="${esc(w.url||'')}" placeholder="https://…"></label>`
   +`<label>${L('Přihlášení','Authentication')}<select name=auth_type onchange=wchAuthFields()>${opt(AUTH,w.auth_type||'none')}</select></label>`
   +`<label data-auth=header>${L('Název hlavičky','Header name')}<input name=auth_header value="${esc(w.auth_header||'')}" placeholder="X-API-Key"></label>`
   +`<label data-auth=oauth2 class=wch-wide>${L('Token URL','Token URL')}<input name=oauth_token_url value="${esc(w.oauth_token_url||'')}" placeholder="https://login…/oauth2/token"></label>`
   +`<label data-auth=oauth2>${L('Způsob získání tokenu (grant)','Grant type')}<select name=oauth_grant onchange=wchAuthFields()>${opt(GRANTS,w.oauth_grant||'client_credentials')}</select></label>`
   +`<label data-auth=oauth2>Client ID<input name=oauth_client_id value="${esc(w.oauth_client_id||'')}" autocomplete=off></label>`
   +`<label data-auth=oauth2>Client Secret<input name=client_secret type=password autocomplete=new-password placeholder="${w.has_credentials?keep:''}"></label>`
   +`<label data-auth=oauth2>Scope<input name=oauth_scope value="${esc(w.oauth_scope||'')}" placeholder="${L('nepovinné, oddělené mezerou','optional, space separated')}"></label>`
   +`<label data-auth="basic oauth2" data-grant=password>${L('Uživatel / API klíč','User / API key')}<input name=username autocomplete=off placeholder="${w.has_credentials?keep:''}"></label>`
   +`<label data-auth="bearer basic header oauth2" data-grant=password>${L('Heslo / token / hodnota hlavičky','Password / token / header value')}<input name=secret type=password autocomplete=new-password placeholder="${w.has_credentials?keep:''}"></label>`
   +`<label data-auth=oauth2 data-grant=refresh_token class=wch-wide>Refresh token<input name=refresh_token type=password autocomplete=new-password placeholder="${w.has_credentials?keep:L('vlož jednou, CARACAL si ho pak obnovuje sám','paste once, CARACAL renews it on its own')}"></label>`
   +`<label data-auth=oauth2>${L('Předání Client Secret','Client authentication')}<select name=oauth_client_auth>${opt(CLIENT_AUTH,w.oauth_client_auth||'body')}</select></label>`
   +`<label data-auth=oauth2>${L('Další parametry tokenu','Extra token parameters')}<input name=oauth_extra value="${esc(w.oauth_extra||'')}" placeholder="audience=https://api.firma.cz"></label>`
   +`<label>${L('Cesta k seznamu v odpovědi','Path to the list in the response')}<input name=list_path value="${esc(w.list_path||'')}" placeholder="${L('prázdné = odpověď je seznam; např. data.tickets','empty = the response is a list; e.g. data.tickets')}"></label>`
   +`<label>${L('Pole s ID položky','Item ID field')}<input name=id_field value="${esc(w.id_field||'id')}"></label>`
   +`<label class=wch-wide>${L('Nadpis oznámení','Notification title')}<input name=title_template value="${esc(w.title_template||'')}" placeholder="${L('Nový ticket #{id}: {subject}','New ticket #{id}: {subject}')}"></label>`
   +`<label class=wch-wide>${L('Text oznámení','Notification text')}<input name=message_template value="${esc(w.message_template||'')}" placeholder="{customer.name} · {group}"></label>`
   +`<label>${L('Úroveň','Level')}<select name=level>${opt(LEVELS,w.level||'info')}</select></label>`
   +`<label>${L('Úroveň podle pole (nepovinné)','Level from field (optional)')}<input name=level_field value="${esc(w.level_field||'')}" placeholder="priority.name"></label>`
   +`<label>${L('Kontrolovat každých (s)','Check every (s)')}<input name=interval type=number min=15 max=86400 value=${w.interval||60}></label>`
   +`<label class=ntf-check><input name=verify_tls type=checkbox ${w.verify_tls===0?'':'checked'}> ${L('Ověřovat HTTPS certifikát','Verify the HTTPS certificate')}</label>`
   +`<div class="dialog-note wch-wide">${L('V nadpisu a textu jde použít pole položky ve složených závorkách, i vnořená: {id}, {subject}, {fields.summary}. Při prvním běhu si hlídač jen zapamatuje, co v systému už je; oznámí až položky, které přibudou potom.','Title and text can use item fields in braces, nested too: {id}, {subject}, {fields.summary}. The first check only remembers what is already there; only items that appear later are announced.')}</div>`
   +`<div class=wch-wide><button type=button class=secondary onclick="wchPreview(${w.id||0})">${L('Vyzkoušet','Try it')}</button><div id=wchPreviewBox></div></div>`;
 }
 function open(title,w,isNew,save){modal(title,form(w,isNew),save);setTimeout(wchAuthFields,0)}
 window.wchAdd=function(){open(L('Nový hlídač','New watcher'),{},true,async f=>{await api('/api/notify/watchers',send('POST',payload(document.getElementById('df'))))})};
 window.wchEdit=async function(id){const w=(await api('/api/notify/watchers')).find(x=>x.id===id);if(!w)return;open(L('Upravit hlídač','Edit watcher'),w,false,async f=>{const r=await api('/api/notify/watchers/'+id,send('PUT',payload(document.getElementById('df'))));if(r.reset)setTimeout(()=>toast(L('Jiná URL nebo seznam: hlídač začíná znovu a stávající položky neoznámí','Different URL or list: the watcher starts again and will not announce existing items')),2500)})};
 window.wchToggle=async function(id,enabled){await api('/api/notify/watchers/'+id,send('PUT',{enabled:!!enabled}));notifications()};
 window.wchDelete=async function(id){if(!confirm(L('Smazat hlídač?','Delete the watcher?')))return;await api('/api/notify/watchers/'+id,{method:'DELETE'});notifications()};
 window.wchCheck=async function(id){try{const r=await api('/api/notify/watchers/'+id+'/check',{method:'POST'});toast(!r.ok?L('Chyba: ','Error: ')+r.error:r.first?L('Zapamatováno položek: ','Items remembered: ')+r.count:L('Nové: ','New: ')+r.new+' · '+L('položek: ','items: ')+r.count)}catch(e){alert(e.message)}notifications()};
 function host(url){try{return new URL(url).host}catch{return url}}
 async function panel(){
  const list=await api('/api/notify/watchers');
  const items=list.map(w=>`<div class=row><div><div class=row-title>${esc(w.name)}</div><div class=muted>${esc(host(w.url))}</div><div class=meta><span class="badge ${w.enabled?'auth':''}">${w.enabled?L('Hlídá','Watching'):L('Vypnuto','Off')}</span><span class=badge>${L('každých','every')} ${w.interval} s</span><span class=badge>${L('Kontrola','Checked')}: ${when(w.last_check)}</span>${w.last_count!=null&&!w.last_error?`<span class=badge>${w.last_count} ${L('položek','items')}</span>`:''}${w.last_error?`<span class="badge wch-error" title="${esc(w.last_error)}">${L('Chyba','Error')}: ${esc(w.last_error.slice(0,80))}</span>`:''}</div></div><div class=actions><button class=secondary onclick=wchCheck(${w.id})>${L('Zkontrolovat teď','Check now')}</button><button class=secondary onclick=wchEdit(${w.id})>${L('Upravit','Edit')}</button><button class=secondary onclick="wchToggle(${w.id},${w.enabled?0:1})">${w.enabled?L('Vypnout','Turn off'):L('Zapnout','Turn on')}</button><button class=danger onclick=wchDelete(${w.id})>${L('Smazat','Delete')}</button></div></div>`).join('');
  return `<div class=panel id=wchPanel><div class=panel-head><h2>${L('Hlídače – CARACAL se ptá aplikací','Watchers – CARACAL asks apps')}</h2><button class=primary onclick=wchAdd()>${L('Nový hlídač','New watcher')}</button></div>${items||`<div class=list-empty>${L('CARACAL se může sám pravidelně ptát API jiné aplikace (helpdesk, Jira, GitLab…) a ukázat každý nový ticket. Přidej hlídač a vyber předvolbu.','CARACAL can ask another app\'s API (helpdesk, Jira, GitLab…) on its own and show every new ticket. Add a watcher and pick a preset.')}</div>`}</div>`;
 }
 const notificationsBeforeWatchers=window.notifications;
 window.notifications=async function(){await notificationsBeforeWatchers();const queue=document.getElementById('ntfQueue');if(queue&&!document.getElementById('wchPanel'))queue.insertAdjacentHTML('afterend',await panel())};
})();


// CARACAL_NOTIFY_AUDIT_UI_V1
// Audit log of the notification settings: who changed what, refused tokens and senders over their limit.
(function(){
 const en=()=>localStorage.getItem('caracal-language')==='en',L=(cs,e)=>en()?e:cs;
 const when=t=>new Date(t*1000).toLocaleString(en()?'en-GB':'cs-CZ');
 async function panel(){
  const a=await api('/api/notify/audit?limit=100');
  const items=a.entries.map(x=>`<div class=row><div><div class=row-title>${esc(x.action)}</div>${x.detail?`<div class=muted>${esc(x.detail)}</div>`:''}<div class=meta><span class=badge>${when(x.ts)}</span>${x.actor?`<span class="badge auth">${esc(x.actor)}</span>`:''}${x.ip?`<span class=badge>${esc(x.ip)}</span>`:''}</div></div></div>`).join('');
  return `<div class=panel id=ntfAudit><div class=panel-head><h2>${L('Audit log','Audit log')}</h2><div class=toolbar><span class=badge>${a.count} / ${a.max} ${L('záznamů','entries')} · ${a.days} ${L('dní','days')}</span><button class=danger-outline onclick=ntfClearAudit()>${L('Smazat audit','Clear audit log')}</button></div></div>${items||`<div class=list-empty>${L('Zatím žádné záznamy.','No entries yet.')}</div>`}${a.count>a.entries.length?`<div class=list-empty>${L('Zobrazeno posledních ','Showing the last ')}${a.entries.length}.</div>`:''}</div>`;
 }
 window.ntfClearAudit=async function(){if(!confirm(L('Smazat audit log? Samotné smazání v něm zůstane zapsané.','Clear the audit log? The clearing itself stays in it.')))return;const r=await api('/api/notify/audit/clear',{method:'POST'});toast(L('Smazáno záznamů: ','Entries deleted: ')+r.deleted);notifications()};
 const notificationsBeforeAudit=window.notifications;
 window.notifications=async function(){await notificationsBeforeAudit();const content=document.getElementById('content');if(content&&!document.getElementById('ntfAudit'))content.insertAdjacentHTML('beforeend',await panel())};
})();


// CARACAL_HTTP_AUTH_UI_V1
// Login profiles of two types: a log-in form on the page (selectors), or HTTP Basic/Digest log-in, the browser's
// own user name / password pop-up, which needs only the address and the credentials.
(function(){
 const en=()=>localStorage.getItem('caracal-language')==='en',L=(cs,e)=>en()?e:cs;
 window.profileTypeChanged=function(){const form=document.getElementById('df'),type=form&&form.querySelector('[name=auth_type]');if(!type)return;const http=type.value==='http';form.querySelectorAll('[data-form-only]').forEach(x=>{x.hidden=http;x.querySelectorAll('input[data-req]').forEach(i=>i.required=!http)});form.querySelectorAll('[data-http-only]').forEach(x=>x.hidden=!http)};
 window.profileForm=function(p={}){
  const type=p.auth_type||'form',keep=L('Prázdné = beze změny','Empty = unchanged');
  return `<label>${L('Typ přihlášení','Login type')}<select name=auth_type onchange=profileTypeChanged()><option value=form ${type==='form'?'selected':''}>${L('Přihlašovací formulář na stránce','Log-in form on the page')}</option><option value=http ${type==='http'?'selected':''}>${L('HTTP přihlášení (vyskakovací okno prohlížeče)','HTTP log-in (the browser pop-up)')}</option></select></label>`
   +`<div class=dialog-note data-http-only hidden>${L('Pro weby, kde prohlížeč sám ukáže okno se jménem a heslem (HTTP Basic/Digest). Přihlášení platí jen pro server z adresy níže; položka playlistu na stejném serveru se otevře na své vlastní adrese.','For websites where the browser itself asks for a user name and password (HTTP Basic/Digest). The log-in is used only for the server in the address below; a playlist item on the same server opens at its own address.')}</div>`
   +`<label>${L('Název','Name')}<input name=name value="${esc(p.name||'')}" required></label>`
   +`<label data-form-only>Login URL<input name=login_url data-req=1 value="${esc(p.login_url||'')}" required></label>`
   +`<label>${L('Cílová URL (u HTTP přihlášení adresa serveru)','Target URL (for HTTP log-in the server address)')}<input name=target_url value="${esc(p.target_url||'')}" required placeholder="https://…"></label>`
   +`<label>${L('Uživatel','User')}<input name=username autocomplete=off placeholder="${p.id?keep:L('Uživatel','User')}" ${p.id?'':'required'}></label>`
   +`<label>${L('Heslo','Password')}<input name=password type=password autocomplete=new-password placeholder="${p.id?keep:L('Heslo','Password')}" ${p.id?'':'required'}></label>`
   +`<label data-form-only>${L('Selektor uživatele','User selector')}<input name=user_selector data-req=1 value="${esc(p.user_selector||'#name')}" required></label>`
   +`<label data-form-only>${L('Selektor hesla','Password selector')}<input name=pass_selector data-req=1 value="${esc(p.pass_selector||'#password')}" required></label>`
   +`<label data-form-only>${L('Selektor tlačítka','Button selector')}<input name=submit_selector data-req=1 value="${esc(p.submit_selector||'#enter')}" required></label>`;
 };
 const addProfileBeforeHttp=window.addProfile;window.addProfile=function(){addProfileBeforeHttp();setTimeout(profileTypeChanged,0)};
 const editProfileBeforeHttp=window.editProfile;window.editProfile=async function(id){await editProfileBeforeHttp(id);setTimeout(profileTypeChanged,0)};
 const profilesBeforeHttp=window.profiles;
 window.profiles=async function(){await profilesBeforeHttp();try{for(const x of await api('/api/profiles')){if(x.auth_type!=='http')continue;const row=document.querySelector(`button[onclick="editProfile(${x.id})"]`)?.closest('.row');const meta=row&&row.querySelector('.meta');if(!meta)continue;meta.innerHTML=`<span class="badge auth">${L('Šifrováno','Encrypted')}</span><span class="badge web">${L('HTTP přihlášení','HTTP log-in')}</span>`;const url=row.querySelector('.muted');if(url)url.textContent=x.target_url}}catch(e){console.warn(e)}};
})();
